<?php
require_once __DIR__.'/includes/auth.php';require_role('Administrator');$me=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');$target=(int)($_POST['id']??0);
 try{if($action==='save'){ $name=trim((string)($_POST['name']??''));$email=mb_strtolower(trim((string)($_POST['email']??'')));$role=(int)($_POST['role_id']??3);$status=in_array($_POST['status']??'', ['active','disabled'],true)?$_POST['status']:'active';$password=(string)($_POST['password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('A valid name and email are required.');if($target){db()->prepare('UPDATE users SET name=?,email=?,role_id=?,status=? WHERE id=?')->execute([mb_substr($name,0,120),$email,$role,$status,$target]);audit('user_updated','Updated user “'.$name.'”.');}else{if(strlen($password)<10)throw new RuntimeException('New user passwords must contain at least 10 characters.');db()->prepare('INSERT INTO users(name,email,role_id,status,password_hash) VALUES(?,?,?,?,?)')->execute([mb_substr($name,0,120),$email,$role,$status,password_hash($password,PASSWORD_DEFAULT)]);audit('user_created','Created user “'.$name.'”.');}flash('success','User saved.');}
 elseif($action==='toggle'&&$target!==$me['id']){db()->prepare("UPDATE users SET status=IF(status='active','disabled','active') WHERE id=?")->execute([$target]);flash('success','Account status changed.');}
 elseif($action==='reset'){ $password=(string)($_POST['new_password']??'');if(strlen($password)<10)throw new RuntimeException('The new password must contain at least 10 characters.');db()->prepare('UPDATE users SET password_hash=?,failed_login_attempts=0,locked_until=NULL WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$target]);audit('user_password_reset','Administrator reset a user password.');flash('success','Password reset. Share it securely and ask the user to change it.');}
 elseif($action==='delete'&&$target!==$me['id']){db()->prepare("UPDATE users SET deleted_at=NOW(),status='disabled' WHERE id=?")->execute([$target]);audit('user_deleted','Soft-deleted user ID '.$target.'.');flash('success','User deleted.');}}
 catch(Throwable $e){flash('danger',$e instanceof PDOException?'That email is already in use or the selected role is invalid.':$e->getMessage());}redirect('users.php');}
$users=db()->query("SELECT u.*,r.name role_name,COUNT(a.id) asset_count FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN assets a ON a.uploaded_by=u.id AND a.deleted_at IS NULL WHERE u.deleted_at IS NULL GROUP BY u.id ORDER BY u.created_at DESC")->fetchAll();$roles=db()->query('SELECT * FROM roles ORDER BY id')->fetchAll();$pageTitle='Users';$pageSubtitle='Manage access, roles and account status';$pageActions='<button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#userModal" id="addUser"><i class="bi bi-person-plus me-1"></i>Add user</button>';require __DIR__.'/includes/header.php';?>
<div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Assets</th><th>Last login</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($users as $row):?><tr><td><div class="d-flex align-items-center gap-2"><span class="avatar"><?php if($row['profile_picture']):?><img src="<?=e(url('profile-image.php?id='.$row['id']))?>" alt=""><?php else:?><?=e(mb_strtoupper(mb_substr($row['name'],0,1)))?><?php endif;?></span><div><strong><?=e($row['name'])?></strong><small class="d-block text-muted"><?=e($row['email'])?></small></div></div></td><td><span class="badge badge-soft"><?=e($row['role_name'])?></span></td><td><span class="badge <?=$row['status']==='active'?'text-bg-success':'text-bg-secondary'?>"><?=e(ucfirst($row['status']))?></span></td><td><?=$row['asset_count']?></td><td><?=e($row['last_login']?date('M j, Y g:i A',strtotime($row['last_login'])):'Never')?></td><td><?=e(date('M j, Y',strtotime($row['created_at'])))?></td><td><div class="dropdown"><button class="btn btn-sm btn-light" data-bs-toggle="dropdown"><i class="bi bi-three-dots"></i></button><ul class="dropdown-menu dropdown-menu-end"><li><button class="dropdown-item edit-user" data-record="<?=e(json_encode(['id'=>$row['id'],'name'=>$row['name'],'email'=>$row['email'],'role_id'=>$row['role_id'],'status'=>$row['status']],JSON_HEX_APOS|JSON_HEX_QUOT))?>">Edit user</button></li><li><button class="dropdown-item reset-user" data-id="<?=$row['id']?>" data-name="<?=e($row['name'])?>">Reset password</button></li><?php if($row['id']!=$me['id']):?><li><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$row['id']?>"><button class="dropdown-item"><?=$row['status']==='active'?'Disable':'Activate'?> account</button></form></li><li><hr class="dropdown-divider"></li><li><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$row['id']?>"><button class="dropdown-item text-danger" data-confirm="Delete this user? Their assets will remain attributed to them.">Delete user</button></form></li><?php endif;?></ul></div></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="modal fade" id="userModal"><div class="modal-dialog"><div class="modal-content"><form method="post" id="userForm"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" id="userId"><div class="modal-header"><h2 class="modal-title fs-5" id="userModalTitle">Add user</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Name</label><input class="form-control mb-3" name="name" id="userName" required><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" id="userEmail" required><div class="row"><div class="col-6"><label class="form-label">Role</label><select class="form-select mb-3" name="role_id" id="userRole"><?php foreach($roles as $role):?><option value="<?=$role['id']?>" <?=setting('default_user_role','3')==$role['id']?'selected':''?>><?=e($role['name'])?></option><?php endforeach;?></select></div><div class="col-6"><label class="form-label">Status</label><select class="form-select" name="status" id="userStatus"><option value="active">Active</option><option value="disabled">Disabled</option></select></div></div><div id="newPassword"><label class="form-label">Temporary password</label><input class="form-control" type="password" name="password"><div class="form-text">At least 10 characters.</div></div></div><div class="modal-footer"><button class="btn btn-primary">Save user</button></div></form></div></div></div>
<div class="modal fade" id="resetModal"><div class="modal-dialog"><div class="modal-content"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="reset"><input type="hidden" name="id" id="resetId"><div class="modal-header"><h2 class="modal-title fs-5">Reset password</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><p id="resetLabel"></p><label class="form-label">New temporary password</label><input class="form-control" type="password" name="new_password" minlength="10" required></div><div class="modal-footer"><button class="btn btn-primary">Reset password</button></div></form></div></div></div>
<?php $extraScripts='<script>const um=new bootstrap.Modal(userModal),rm=new bootstrap.Modal(resetModal);addUser.onclick=()=>{userForm.reset();userId.value="";userModalTitle.textContent="Add user";newPassword.classList.remove("d-none");userForm.password.required=true};document.querySelectorAll(".edit-user").forEach(b=>b.onclick=()=>{const r=JSON.parse(b.dataset.record);userId.value=r.id;userName.value=r.name;userEmail.value=r.email;userRole.value=r.role_id;userStatus.value=r.status;userModalTitle.textContent="Edit user";newPassword.classList.add("d-none");userForm.password.required=false;um.show()});document.querySelectorAll(".reset-user").forEach(b=>b.onclick=()=>{resetId.value=b.dataset.id;resetLabel.textContent="Set a temporary password for "+b.dataset.name+".";rm.show()});</script>';require __DIR__.'/includes/footer.php';?>
